    sep = next(grid[r][0] for r in range(h) if len(set(grid[r])) == 1)
    row_seps = [r for r in range(h) if all(x == sep for x in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    counts = {}
    for row in grid:
        for x in row:
            if x != sep:
                counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)
    object_color = min((x for x in counts if x != background),
                       key=lambda x: counts[x])

    rb = [-1] + row_seps + [h]
    cb = [-1] + col_seps + [w]
    result = []
    for i in range(len(rb) - 1):
        r0, r1 = rb[i] + 1, rb[i + 1]
        outrow = []
        for j in range(len(cb) - 1):
            c0, c1 = cb[j] + 1, cb[j + 1]
            n = sum(grid[r][c] == object_color
                    for r in range(r0, r1)
                    for c in range(c0, c1))
            outrow.append(1 if n >= 2 else background)
        result.append(outrow)
    return result
